mapper.update:
update blogs
set
  click_num = #{clickNum,jdbcType=BIGINT}
where id = #{id,jdbcType=INTEGER}

mapper.select:
select distinct(blogs.id), blogs.title, blogs.click_num, blogs.user_id, blogs.create_time,blogs.sub_content,blogs.cover, blog_type.type_name as typeName, tag1.tag_name as tagList from blogs left join blog_type on blog_type.id = blogs.type_id left join tags tag1 on tag1.blog_id = blogs.id left join tags tag2 on tag2.blog_id = blogs.id
blogs.status = '1'
and tag2.tag_name = #{tagName}
and blogs.type_id = #{typeId}
and blogs.create_time > startTime and blogs.create_time < now()
order by blogs.create_time desc,blogs.id desc limit #{index},#{pageSize}

select count(1) from blogs left join blog_type on blog_type.id = blogs.type_id left join tags on tags.blog_id = blogs.id
blogs.status = '1'
and tags.tag_name = #{tagName}
and blogs.type_id = #{typeId}
and blogs.create_time > startTime and blogs.create_time < now()
